      const activeHumans = (humans || []).filter((human) => !human.isIncapacitated && !human.isCocooned);
      let closestDistance = Infinity;
      let closestDy = 0;
      let contactCount = 0;

      const playerFacing = player.mesh ? player.mesh.rotation.y : 0;

