        window.HiveSystems?.vfx?.burst?.(post.x, post.z, 0xef4444, 38, 0.25, 2.5);
        if (post.mesh) post.mesh.visible = false;
        showToast('AFFÛT SNIPER M42A DÉTRUIT : Faisceau thermique neutralisé et munitions de 10x30mm détruites !');
