      if (distSprinkler) stationMap.triggerFireSprinklers(distSprinkler);
      const distChute = (stationMap.toxicWasteChutes || []).find((tw) => !tw.isActive && Math.hypot(tw.x - playerCreature.x, tw.z - playerCreature.z) <= 15);
